?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>My Orders | Dionisio Fitness Center</title><link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@400;500;600;700;800;900&display=swap" rel="stylesheet"><link rel="stylesheet" href="css/style.css"></head><body class="auth-page"><div class="auth-shell wide-shell"><a href="index.php" class="auth-brand"><span class="brand-mark">D</span><span class="brand-text"><strong>DIONISIO</strong><small>FITNESS CENTER</small></span></a><div class="account-card"><div class="auth-copy"><p class="eyebrow">SHOPPING</p><h1>MY <span>ORDERS.</span></h1><p>Your previous Dionisio merch orders.</p></div><?php if(!$orders):?><div class="empty-state"><h3>NO ORDERS YET</h3><a class="btn btn-red" href="merch.php">SHOP MERCH</a></div><?php else:?><div class="order-list"><?php foreach($orders as $o):?><a class="order-row" href="order_details.php?id=<?=(int)$o['order_id']?>"><div><span>ORDER #<?=str_pad((string)$o['order_id'],4,'0',STR_PAD_LEFT)?></span><strong><?=e(date('F j, Y g:i A',strtotime($o['order_date'])))?></strong></div><div><b>₱<?=number_format((float)$o['total_amount'],2)?></b><em><?=e($o['status'])?></em></div></a><?php endforeach;?></div><?php endif;?><a class="auth-back" href="account.php">← BACK TO MY ACCOUNT</a></div></div></body></html>
